// Deno is a legitimate JavaScript/TypeScript runtime.  It is used to run scripts, build web servers, create command-line tools, and compile code into self-contained executables. 
// This rule fires when a Deno process is started with a command line matching suspicious patterns: javascript with base64, eval(, http, or javascript import. 
// Such patterns are commonly used to run inline or remote scripts and can indicate abuse.
let deno_javascript_base64 = 
SecurityEvent
| where Process has "deno.exe"
| where CommandLine has_all ("javascript","base64");
let deno_javascript_eval = 
SecurityEvent
| where Process has "deno.exe"
| where CommandLine has_all ("eval","http","javascript","import");
union isfuzzy=true
deno_javascript_base64, deno_javascript_eval
| extend
    ComputerName = tostring(column_ifexists("Computer", "")),
    Account = tostring(
        coalesce(
            column_ifexists("SubjectUserName", ""),
            column_ifexists("Account", "")
        )
    ),
    CommandLineMapped = tostring(column_ifexists("ServiceFileName", ""))
